import * as Print from 'expo-print';
import * as Sharing from 'expo-sharing';
import { File, Paths } from 'expo-file-system';
import { Platform } from 'react-native';

const PYSSUM_LOGO_BASE64 = "data:image/png;base64,";

export const generateInvoicePDF = async (cart, customer, grandTotal, invoiceNumber) => {
    const today = new Date().toLocaleDateString('en-IN');
    const tableRows = cart.map((item, index) => `
        <tr>
            <td>${index + 1}</td>
            <td>
                <div class="item-desc">${item.item_name}</div>
                <div class="qty">Qty: ${item.quantity} ${item.unit || ''}</div>
            </td>
            <td>₹${item.sale_rate}</td>
            <td style="font-weight: bold;">₹${(item.sale_rate * item.quantity).toFixed(2)}</td>
        </tr>
    `).join('');
    const htmlContent = `
    <html>
    <head>
        <style>
            body { 
                font-family: 'Times New Roman', Times, serif; 
                padding: 40px; 
                color: #000; 
            }
            .header-container { 
                display: flex; 
                justify-content: space-between; 
                align-items: flex-start; 
            }
            .left-header { 
                flex: 1; 
            }
            .right-header { 
                flex: 1; 
                display: flex;
                flex-direction: column;
                align-items: flex-end;
            }
            .brand-container {
                max-width: 260px;
                text-align: center;
            }
            .title { 
                font-size: 32px; 
                font-weight: 900; 
                margin: 0; 
            }
            .invoice-num { 
                font-size: 20px; 
                color: #333;
                margin-top: 8px; 
            }
            
            /* Logo & Brand Styling */
            .logo-img {
                width: 140px;
                height: auto;
                margin-bottom: 5px;
            }
            .brand-name { 
                font-size: 42px; 
                font-weight: 900; 
                font-family: 'Helvetica', sans-serif;
                letter-spacing: 1px; 
                margin-bottom: 10px; 
            }
            .p { color: #2c3e50; } 
            .y { color: #2c3e50; } 
            .s1 { color: #2c3e50; } 
            .s2 { color: #2c3e50; } 
            .u { color: #2c3e50; } 
            .m { color: #2c3e50; }
            
            .company-address { 
                font-size: 14px; 
                line-height: 1.5; 
                color: #000; 
                text-align: left; 
            }
            
            /* Details Section */
            .details-container { 
                display: flex; 
                justify-content: space-between; 
                margin-top: 50px; 
                font-size: 18px; 
                line-height: 1.6; 
            }
            
            /* Table Styling */
            table { 
                width: 100%; 
                border-collapse: separate; 
                border-spacing: 0;
                margin-top: 40px; 
            }
            th { 
                background-color: #000000; 
                color: #ffffff; 
                padding: 15px; 
                text-align: left; 
                font-family: 'Helvetica', sans-serif;
                font-size: 16px;
            }
            th:first-child {
                border-top-left-radius: 10px;
                border-bottom-left-radius: 10px;
                text-align: center;
            }
            th:last-child {
                border-top-right-radius: 10px;
                border-bottom-right-radius: 10px;
                text-align: right;
            }
            td { 
                padding: 15px; 
                vertical-align: top;
            }
            .item-desc { 
                font-weight: bold; 
                font-size: 18px; 
            }
            .qty { 
                font-size: 16px; 
                font-weight: bold; 
                margin-top: 6px; 
            }

            /* Footer Styling */
            .footer-container {
                display: flex;
                justify-content: space-between;
                align-items: flex-end;
                margin-top: 80px;
                font-size: 20px;
            }
            .signature-line {
                display: inline-block;
                width: 200px;
                border-bottom: 1px solid #000;
                margin-left: 10px;
            }
        </style>
    </head>
    <body>
        <div class="header-container">
            <div class="left-header">
                <h1 class="title">TAX INVOICE</h1>
                <div class="invoice-num">Invoice#: ${invoiceNumber}</div>
            </div>
            <div class="right-header">
                <div class="brand-container">
                    <!-- ADD YOUR ONLINE LOGO URL HERE -->
                    <img src="${PYSSUM_LOGO_BASE64}" class="logo-img" />
                    
                    <div class="brand-name">
                        <span class="p">P</span><span class="y">Y</span><span class="s1">S</span><span class="s2">S</span><span class="u">U</span><span class="m">M</span>
                    </div>
                    <div class="company-address">
                        537/8, Puraniya, Sitapur Road,<br/>
                        Lucknow-226020, Uttar Pradesh,<br/>
                        India
                    </div>
                </div>
            </div>
        </div>

        <div class="details-container">
            <div>
                <div>Invoice Date: ${today}</div>
                <div>Due Date: ${today}</div>
            </div>
            <div>
                <div>Billed To: ${customer.customer_name}</div>
                <div>Contact Number: ${customer.phone_number}</div>
                <div>Address: ${customer.address || ''}</div>
            </div>
        </div>

        <table>
            <thead>
                <tr>
                    <th style="width: 5%;">#</th>
                    <th style="width: 55%;">Item & Description</th>
                    <th style="width: 20%;">MRP</th>
                    <th style="width: 20%;">Total Cost</th>
                </tr>
            </thead>
            <tbody>
                ${tableRows}
            </tbody>
        </table>

        <div class="footer-container">
            <div>Authorized Signature: <span class="signature-line"></span></div>
            <div>Grand Total: ₹${grandTotal.toFixed(2)}</div>
        </div>
    </body>
    </html>
    `;

    try {
        if (Platform.OS === 'web') {
            const printWindow = window.open('', '_blank');
            
            if (printWindow) {
                // Write the HTML directly to the new window
                printWindow.document.open();
                printWindow.document.write(htmlContent);
                printWindow.document.close();
                
                printWindow.focus();
                setTimeout(() => {
                    printWindow.print();
                    
                    // Automatically close the temporary tab after they save/cancel
                    printWindow.onafterprint = () => {
                        printWindow.close();
                    };
                }, 500);
            } else {
                // Fallback if the user has a strict pop-up blocker enabled
                alert("Please allow pop-ups in your browser to print invoices.");
            }
        } else {
            const { base64 } = await Print.printToFileAsync({ 
                html: htmlContent,
                base64: true 
            });
            const safeFile = new File(Paths.document, `PYSSUM_Invoice_${invoiceNumber}.pdf`);
            await safeFile.write(base64, { encoding: 'base64' });
            await Sharing.shareAsync(safeFile.uri, { UTI: '.pdf', mimeType: 'application/pdf' });
        }
    } catch (error) {
        console.error("Error generating PDF:", error);
    }
};